    public function __construct(
        private RandomizerInterface $random,
    ) {}

    /** Ключ фраз игрока: заклинание, тип оружия по навыку или общий набор. */
    public function weaponKey(?int $skillId, bool $isMagic): string
    {
        if ($isMagic) {
            return 'magic';
        }

        return self::WEAPON_BY_SKILL[$skillId ?? 0] ?? 'generic';
    }

    public function playerHit(string $weaponKey, bool $critical): string
    {
        return $this->pick(self::PLAYER[$weaponKey] ?? self::PLAYER['generic'], $critical ? 'crit' : 'hit');
    }

    public function playerMiss(string $weaponKey): string
    {
        return $this->pick(self::PLAYER[$weaponKey] ?? self::PLAYER['generic'], 'miss');
    }

    public function monsterHit(?MonsterAttackStyle $style, bool $critical): string
    {
        return $this->pick(self::MONSTER[($style ?? MonsterAttackStyle::STRIKE)->value], $critical ? 'crit' : 'hit');
    }

    public function monsterMiss(?MonsterAttackStyle $style): string
    {
        return $this->pick(self::MONSTER[($style ?? MonsterAttackStyle::STRIKE)->value], 'miss');
    }

    /** Строка гибели монстра (с найденными монетами или без). */
    public function monsterDeath(?MonsterAttackStyle $style, bool $withMoney): string
    {
        return $this->pick(self::DEATH[($style ?? MonsterAttackStyle::STRIKE)->value], $withMoney ? 'money' : 'plain');
    }

    /** @param array<string, list<string>> $set */
    private function pick(array $set, string $kind): string
    {
        $variants = $set[$kind];

        return $variants[$this->random->between(0, count($variants) - 1)];
    }
}
